// Fallback icon for skills without custom icons
const FallbackIcon = ({ name }: { name: string }) => (
  <div className="w-full h-full flex items-center justify-center bg-portfolio-lightNavy/50 rounded-lg">
    <span className="text-xs font-bold text-portfolio-lightSlate">
      {name.substring(0, 2).toUpperCase()}
    </span>
  </div>
);

const colorMap: Record<string, string> = {
  "portfolio-highlight": "#569CD6",
  "portfolio-blue": "#569CD6",
  "portfolio-teal": "#4EC9B0",
  "portfolio-slate": "#858585",
  "portfolio-lightSlate": "#9D9D9D",
};

const TechStackIcons: React.FC<TechStackIconsProps> = ({
  skills,
  categoryColor,
}) => {
  return (
    <TooltipProvider>
      <div className="flex flex-wrap gap-4 justify-center">
        {skills.map((skill, idx) => {
          const icon = techIcons[skill.name];
          return (
            <Tooltip key={idx}>
              <TooltipTrigger asChild>
                <div
                  className="group relative w-16 h-16 md:w-20 md:h-20 rounded-xl bg-portfolio-lightNavy/30 border border-portfolio-slate/10 hover:border-portfolio-highlight/30 p-3 cursor-pointer transition-all duration-300 hover:scale-110 hover:shadow-lg hover:shadow-portfolio-highlight/10"
                  style={{
                    ["--hover-color" as any]: colorMap[categoryColor],
                  }}
                >
                  <div className="w-full h-full flex items-center justify-center">
                    {icon ? icon : <FallbackIcon name={skill.name} />}
                  </div>
                  {/* Skill level indicator */}
                  <div
                    className="absolute -bottom-1 left-1/2 -translate-x-1/2 h-1 rounded-full transition-all duration-300 opacity-0 group-hover:opacity-100"
                    style={{
                      width: `${skill.level}%`,
                      maxWidth: "90%",
                      backgroundColor: colorMap[categoryColor],
                    }}
                  />
                </div>
              </TooltipTrigger>
              <TooltipContent
                side="bottom"
                className="bg-portfolio-lightNavy border-portfolio-slate/30"
              >
                <div className="text-center">
                  <p className="text-portfolio-white font-semibold">
                    {skill.name}
                  </p>
                  <p
                    className="text-sm font-mono"
                    style={{ color: colorMap[categoryColor] }}
                  >
                    {skill.level}% proficiency
                  </p>
                </div>
              </TooltipContent>
            </Tooltip>
          );
        })}
      </div>
    </TooltipProvider>
  );
};

export default TechStackIcons;
